//! Fixtures and assertions for uidiff tests.
const std = @import("std");
const values = @import("value.zig");
const regions = @import("diff/regions.zig");
const rows = @import("diff/rows.zig");
/// Procedural RGBA canvases and painters.
pub const canvas = @import("testing/canvas.zig");
/// Assertions over results from the comparison API.
pub const expect = @import("testing/expect.zig");

/// Render-plan operations examined by sheet scenarios.
pub const sheet = @import("testing/sheet.zig");

/// Small arbitrary RGBA inputs generated by Smith.
pub const fuzz = @import("testing/fuzz.zig");

/// Smallest changed-pixel support that can become a region.
pub const min_region_pixels = regions.min_region_pixels;
/// Initial grouping distance in CSS pixels.
pub const merge_gap = regions.merge_gap;
/// Row alignment's insertion and deletion budget.
pub const max_edits = rows.max_edits;

/// Compares the full RGBA pixels of two runs.
pub fn sameRun(a: []const values.Pixel, b: []const values.Pixel) bool {
    return std.mem.eql(u8, std.mem.sliceAsBytes(a), std.mem.sliceAsBytes(b));
}
